from tkinter import Tk, Label, Button

class CaptchaBait(object):
    def __init__(self):
        self.root = Tk()
        self.root.title("CaptchaBait")
        self.label = Label(self.root, text="Welcome to CaptchaBait", font=('Arial', 20))
        self.label.pack()
        self.challenge_button = Button(self.root, text="Enter Your Password", command=self.challenge)
        self.challenge_button.pack()
        self.root.after(1, self.wait)

    def challenge(self):
        self.label.pack_forget()
        self.display_challenge()

    def display_challenge(self):
        challenge_code = random.randint(1, 10)
        tk = Tk()
        tk.title("Challenge")
        tk.geometry("200x50")
        tk.Label(tk, text="GDStatus: 1/10: " + str(challenge_code), font=('Arial', 14)).pack()
        tk.Label(tk, text="Ans:", font=('Arial', 22)).pack()
        tk.pack()
        button = tk.Button(tk, text="Submit", command=self.submit_ans)
        button.pack()
        tk.mainloop()

    def submit_ans(self):
        self.label.pack()
        self.display_result()

    def display_result(self):
        password = getpass("Enter your password: ")
        if password == "123456":
            print("Congratulations, you won a prize!")
        else:
            print("Invalid password. Better luck next time.")

    def wait(self):
        self.challenge_button.pack_forget()
        self.label = Label(self.root, text="", font=('Arial', 20))
        self.label.pack()
        time.sleep(2)
        self.challenge_button.pack()

if __name__ == "__main__":
    CaptchaBait()
